package rpg.engine.script;
import java.util.*;import static rpg.engine.script.Ast.*;
public final class Parser {private final List<Token> t;private int p;public Parser(String s){t=new Lexer(s).lex();}private Token peek(){return t.get(p);}private Token take(){return t.get(p++);}private boolean at(Token.Type x){return peek().type()==x;}private void eat(Token.Type x){if(!at(x))throw err("expected "+x+", got "+peek().type());take();}private RuntimeException err(String s){var q=peek();return new IllegalArgumentException("script "+q.line()+":"+q.col()+": "+s);}public Block parse(){var b=new ArrayList<Stmt>();while(!at(Token.Type.EOF))b.add(stmt());return new Block(b);}private Stmt stmt(){if(at(Token.Type.LET)){take();String n=takeIdent();eat(Token.Type.ASSIGN);var e=expr();semi();return new Let(n,e);}if(at(Token.Type.IF)){take();eat(Token.Type.LP);var c=expr();eat(Token.Type.RP);var y=block();Block n=new Block(List.of());if(at(Token.Type.ELSE)){take();n=block();}return new If(c,y,n);}if(at(Token.Type.RETURN)){take();var e=expr();semi();return new Return(e);}var e=expr();if(e instanceof Variable v&&at(Token.Type.ASSIGN)){take();var r=expr();semi();return new Assign(v.name(),r);}semi();return new ExprStmt(e);}private Block block(){eat(Token.Type.LBRACE);var b=new ArrayList<Stmt>();while(!at(Token.Type.RBRACE)){if(at(Token.Type.EOF))throw err("unclosed block");b.add(stmt());}take();return new Block(b);}private void semi(){if(at(Token.Type.SEMICOLON))take();}private String takeIdent(){if(!at(Token.Type.IDENT))throw err("identifier expected");return take().text();}
 private Expr expr(){return equality();}private Expr equality(){Expr x=compare();while(at(Token.Type.EQ)||at(Token.Type.NE)){String o=take().type()==Token.Type.EQ?"==":"!=";x=new Binary(o,x,compare());}return x;}private Expr compare(){Expr x=term();while(at(Token.Type.LT)||at(Token.Type.GT)||at(Token.Type.LE)||at(Token.Type.GE)){var z=take();x=new Binary(z.type().name().toLowerCase(),x,term());}return x;}private Expr term(){Expr x=factor();while(at(Token.Type.PLUS)||at(Token.Type.MINUS)){String o=take().text();x=new Binary(o,x,factor());}return x;}private Expr factor(){Expr x=unary();while(at(Token.Type.STAR)||at(Token.Type.SLASH)){String o=take().text();x=new Binary(o,x,unary());}return x;}private Expr unary(){if(at(Token.Type.MINUS)){take();return new Unary("-",unary());}return postfix(primary());}private Expr postfix(Expr x){while(true){if(at(Token.Type.DOT)){take();x=new Member(x,takeIdent());}else if(at(Token.Type.LP)){take();var a=new ArrayList<Expr>();if(!at(Token.Type.RP)){do{a.add(expr());if(!at(Token.Type.COMMA))break;take();}while(true);}eat(Token.Type.RP);x=new Call(x,a);}else break;}return x;}private Expr primary(){var q=take();return switch(q.type()){case NUMBER->new Literal(Double.parseDouble(q.text()));case STRING->new Literal(q.text());case TRUE->new Literal(true);case FALSE->new Literal(false);case NIL->new Literal(null);case IDENT->new Variable(q.text());case LP->{var e=expr();eat(Token.Type.RP);yield e;}default->throw err("expression expected");};}}
